What is the output of the following C++ code?

```cpp
#include <iostream>
class Base {
public:
    virtual void print() { std::cout << "Base"; }
};
class Derived : public Base {
public:
    void print() { std::cout << "Derived"; }
};
int main() {
    Base* b = new Derived();
    b->print();
    return 0;
}
```

