What is the output of the following C++ code involving template specialization?

```cpp
#include <iostream>
template<typename T>
void foo(T) { std::cout << "primary"; }

template<>
void foo(int*) { std::cout << "int*"; }

template<typename T>
void foo(T*) { std::cout << "T*"; }

int main() {
    int* p = nullptr;
    foo(p);
    return 0;
}
```

What does the following C++ code print?

```cpp
#include <iostream>
struct A {
    A() { std::cout << "A"; }
    ~A() { std::cout << "~A"; }
};
struct B : A {
    B() { std::cout << "B"; }
    ~B() { std::cout << "~B"; }
};
int main() {
    A* obj = new B();
    delete obj;
    return 0;
}
```

In C++, what is the result of the following expression involving SFINAE?

```cpp
#include <iostream>
#include <type_traits>
template<typename T, typename = std::enable_if_t<std::is_integral_v<T>>>
void check(T) { std::cout << "integral"; }

template<typename T, typename = std::enable_if_t<std::is_floating_point_v<T>>>
void check(T) { std::cout << "floating"; }

int main() {
    check(3.14);
    return 0;
}
```
